            C++

    #include <iostream>
using namespace std;

double power(double b, int e) {

    // Base Case: pow(b, 0) = 1
    if (e == 0)
        return 1;

    if (e < 0)
        return 1 / power(b, -e);

    // For all other cases
    return b * power(b, e - 1);
}

int main() {
    double b = 3.0;
    int e = 5;
    double res = power(b, e);
    cout << res;
    return 0;
}


