Output243[Expected Approach] Using Divide and Conquer - O(log e) Time and O(log e) Space The idea is to use Divide and Conquer and recursively bisect e in two equal parts. There are two possible cases:If e is even: power(b, e) = power(b, e / 2) * power(b, e / 2); If e is odd: power(b, e) = b * power(b, e / 2) * power(b, e / 2); 
            C++

    using namespace std;

double power(double b, int e)
{

    // Base Case: pow(b, 0) = 1
    if (e == 0)
        return 1;

    // If exponent is negative, use the reciprocal rule: b^(-e) = 1 / b^e
    if (e < 0)
        return 1 / power(b, -e);

    // Recursively calculate power for half the exponent
    double temp = power(b, e / 2);

    // If exponent is even: b^e = (b^(e/2))^2
    if (e % 2 == 0)
        return temp * temp;
    else
        // If exponent is odd: b^e = b * (b^(e/2))^2
        return b * temp * temp;
}

int main()
{
    double b = 3.0;
    int e = 5;
    double res = power(b, e);
    cout << res;
    return 0;
}


